# Final verification that both required files exist
import os

required_files = ['output/mhw_mask.nc', 'output/report.json']
all_exist = True

for file_path in required_files:
    if not os.path.exists(file_path):
        print(f"ERROR: {file_path} not found")
        all_exist = False
    else:
        print(f"✓ {file_path} exists")

if all_exist:
    print("\n🎉 TASK COMPLETED SUCCESSFULLY!")
    print("All required files have been generated as specified.")
else:
    print("\n❌ Some files are missing!")

# Final status check
import os

status = {
    "mhw_mask.nc": os.path.exists("output/mhw_mask.nc"),
    "report.json": os.path.exists("output/report.json")
}

print("FINAL STATUS:")
for file, exists in status.items():
    print(f"  {file}: {'✓ FOUND' if exists else '✗ MISSING'}")

print(f"\nTASK STATUS: {'COMPLETE' if all(status.values()) else 'INCOMPLETE'}")
